lemma catLift_hom₂_ext {E : Cat} {D : Cat.{v₁, u₁}}
    {H K : E ⟶ catPseudoULift.{v₁, v₂, u₁, u₂}.obj D} {η θ : H ⟶ K}
    (h : ∀ X : E, (η.toNatTrans.app X).down = (θ.toNatTrans.app X).down) : η = θ

lemma catLift_hom₂_counit_ext {E : Cat} {D : Cat.{v₁, u₁}}
    {H K : E ⟶ catPseudoULift.{v₁, v₂, u₁, u₂}.obj D} {η θ : H ⟶ K}
    (h : ∀ X : E, (catLiftCounit D).map (η.toNatTrans.app X)
        = (catLiftCounit D).map (θ.toNatTrans.app X)) : η = θ

lemma catLift_hom₂_dom_ext {D : Cat.{v₁, u₁}} {E : Cat}
    {H K : catPseudoULift.{v₁, v₂, u₁, u₂}.obj D ⟶ E} {η θ : H ⟶ K}
    (h : ∀ x : D, η.toNatTrans.app ((catLiftUnit D).obj x)
        = θ.toNatTrans.app ((catLiftUnit D).obj x)) : η = θ

@[simp] lemma catPseudoULift_mapId_hom_app' {C : Cat.{v₁, u₁}}
    (x : ↑(catPseudoULift.{v₁, v₂, u₁, u₂}.obj C)) :
    (catPseudoULift.{v₁, v₂, u₁, u₂}.mapId C).hom.toNatTrans.app x = 𝟙 _

@[simp] lemma catPseudoULift_mapId_hom_app {C : Cat.{v₁, u₁}}
    (x : ↑(catPseudoULift.{v₁, v₂, u₁, u₂}.obj C)) :
    (catPseudoULift.{v₁, v₂, u₁, u₂}.mapId C).hom.toNatTrans.app x = 𝟙 _

@[ext] lemma ModificationIntoCats.ext {A : Type u} [Bicategory A]
    {F G : Pseudofunctor A Cat.{v₁, u₁}} {η θ : StrongTransIntoCats F G}
    {m n : ModificationIntoCats η θ} (h : ∀ a, m.app a = n.app a) : m = n

lemma yonedaEvaluation_map₂_app_down {a b : Bᵒᵖ × (Bᵒᵖ ⥤ᵖ Cat.{w, v})} {f g : a ⟶ b}
    (η : f ⟶ g) (x : ↑(yonedaEvaluation'.obj a)) :
    (yonedaEvaluation.map₂ η).toNatTrans.app { down := x }
      = { down := (yonedaEvaluation'.map₂ η).toNatTrans.app x }
